// The `get_config_schema` tool: the versioned config schema this repository builds.
// This package is a thin adapter over the verify API and the spec (AGENTS.md): the tool hands
// back `spec/config/v0.schema.json` exactly as it sits on disk. That file is generated by
// `npm run schema:build` from the fragments under `spec/config/fragments/`, so nothing here
// retypes, rebuilds, or reorders it, and the tool reads no user file and never touches the
// network — the `$id` URL is where the schema will be published, not where it is fetched from.

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** Tool name, as a client would call it. Part of the MCP surface; stable once released. */
export const GET_CONFIG_SCHEMA_NAME = "get_config_schema";

export const GET_CONFIG_SCHEMA_DESCRIPTION =
  "Return the versioned Seaworthy config schema — the same built document at spec/config/v0.schema.json that a seaworthy.config.json points at with its $schema key. The JSON comes back exactly as this repository builds it; nothing is fetched.";

/**
 * The built schema file, located relative to this module: from `packages/mcp/dist/src/` four
 * levels up is the repository root, the way the package tests reach the spec. Pre-alpha note:
 * this resolves inside a Seaworthy checkout (the repository or a `github:` install of it), not
 * inside a standalone published package; there is no published package yet.
 */
const SCHEMA_FILE = new URL("../../../../spec/config/v0.schema.json", import.meta.url);

/**
 * The config schema JSON text, byte-identical to the file on disk. Throws when the file is
 * missing, naming the file and the command that writes it, because the schema is generated,
 * never hand-edited: `npm run schema:build`.
 */
export function getConfigSchema(): string {
  try {
    return readFileSync(fileURLToPath(SCHEMA_FILE), "utf8");
  } catch (error) {
    throw new Error(`cannot read ${fileURLToPath(SCHEMA_FILE)}: ${error instanceof Error ? error.message : String(error)}; the config schema is built from the fragments under spec/config/fragments/ — regenerate it with \`npm run schema:build\``);
  }
}
